#!/usr/bin/env python3
"""UK Retail Fuel Price Trend Analysis — February 2026.
Generates the final HTML report at /app/output/final_report.html."""

import csv
import json
import io
import base64
from collections import defaultdict, Counter
from datetime import datetime, timezone
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import seaborn as sns

# ── Global style ──────────────────────────────────────────────────────────────
plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'font.size': 10,
    'axes.titlesize': 13,
    'axes.titleweight': 'bold',
    'axes.labelsize': 11,
    'figure.dpi': 120,
    'savefig.bbox': 'tight',
    'savefig.pad_inches': 0.15,
})
PALETTE = sns.color_palette("Set2", 6)
PALETTE_DICT = {
    'E10': PALETTE[0],
    'B7_STANDARD': PALETTE[1],
    'E5': PALETTE[2],
    'B7_PREMIUM': PALETTE[3],
    'B10': PALETTE[4],
    'HVO': PALETTE[5],
}

# ── Data Loading ──────────────────────────────────────────────────────────────
def load_data(path='/app/benchmark/data.csv'):
    rows = []
    with open(path, 'r') as f:
        reader = csv.DictReader(f)
        for r in reader:
            r['price_pence'] = float(r['price_pence'])
            r['recorded_at_dt'] = datetime.fromisoformat(r['recorded_at'].replace('Z', '+00:00'))
            r['source_updated_at_dt'] = datetime.fromisoformat(r['source_updated_at'].replace('Z', '+00:00'))
            r['update_lag_hours'] = (r['recorded_at_dt'] - r['source_updated_at_dt']).total_seconds() / 3600
            rows.append(r)
    return rows

def filter_outliers_iqr(rows):
    """Per-fuel-type IQR filter: keep values within [Q1 - 1.5*IQR, Q3 + 1.5*IQR]."""
    by_fuel = defaultdict(list)
    for r in rows:
        by_fuel[r['fuel_type']].append(r['price_pence'])
    bounds = {}
    for ft, vals in by_fuel.items():
        arr = np.array(vals)
        q1, q3 = np.percentile(arr, [25, 75])
        iqr = q3 - q1
        bounds[ft] = (q1 - 1.5 * iqr, q3 + 1.5 * iqr)
    clean, flagged = [], []
    for r in rows:
        lo, hi = bounds[r['fuel_type']]
        if lo <= r['price_pence'] <= hi:
            clean.append(r)
        else:
            flagged.append(r)
    return clean, flagged, bounds

# ── Statistics helpers ────────────────────────────────────────────────────────
def fuel_stats(rows):
    """Compute per-fuel-type stats from clean rows."""
    by_fuel = defaultdict(list)
    for r in rows:
        by_fuel[r['fuel_type']].append(r['price_pence'])
    out = {}
    for ft, vals in sorted(by_fuel.items()):
        arr = np.array(vals)
        out[ft] = {
            'count': len(arr),
            'mean': np.mean(arr),
            'median': np.median(arr),
            'std': np.std(arr, ddof=1),
            'min': np.min(arr),
            'max': np.max(arr),
            'q1': np.percentile(arr, 25),
            'q3': np.percentile(arr, 75),
            'iqr': np.percentile(arr, 75) - np.percentile(arr, 25),
            'spread': np.max(arr) - np.min(arr),
        }
    return out

def station_coverage(rows, clean_rows):
    """Compute per-station fuel type counts."""
    station_fuels = defaultdict(set)
    for r in rows:
        station_fuels[r['node_id']].add(r['fuel_type'])
    counts = Counter(len(v) for v in station_fuels.values())
    # per-fuel-type station count
    fuel_stations = defaultdict(set)
    for r in rows:
        fuel_stations[r['fuel_type']].add(r['node_id'])
    fuel_station_counts = {ft: len(stations) for ft, stations in fuel_stations.items()}
    return {
        'total_stations': len(station_fuels),
        'distribution': dict(sorted(counts.items())),
        'fuel_station_counts': fuel_station_counts,
    }

def update_lag_stats(rows):
    """Compute update-lag statistics per fuel type."""
    by_fuel = defaultdict(list)
    for r in rows:
        by_fuel[r['fuel_type']].append(r['update_lag_hours'])
    out = {}
    for ft, lags in sorted(by_fuel.items()):
        arr = np.array(lags)
        out[ft] = {
            'mean': np.mean(arr),
            'median': np.median(arr),
            'std': np.std(arr, ddof=1),
            'min': np.min(arr),
            'max': np.max(arr),
            'p90': np.percentile(arr, 90),
            'p95': np.percentile(arr, 95),
            'p99': np.percentile(arr, 99),
        }
    return out

# ── Plotting helpers ──────────────────────────────────────────────────────────
def fig_to_b64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=120)
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return f'data:image/png;base64,{b64}'

def plot_price_distribution(stats, rows):
    """Violin plot of price distribution by fuel type."""
    fig, ax = plt.subplots(figsize=(10, 5.5))
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    data = []
    positions = []
    labels = []
    by_fuel = defaultdict(list)
    for r in rows:
        by_fuel[r['fuel_type']].append(r['price_pence'])
    for i, ft in enumerate(fuel_order):
        if ft in by_fuel and len(by_fuel[ft]) > 0:
            data.append(by_fuel[ft])
            positions.append(i)
            labels.append(ft)
    parts = ax.violinplot(data, positions=positions, showmeans=True, showmedians=True,
                          widths=0.7)
    for i, pc in enumerate(parts['bodies']):
        pc.set_facecolor(PALETTE[i % len(PALETTE)])
        pc.set_alpha(0.7)
    for part in ('cmeans', 'cmedians', 'cbars', 'cmins', 'cmaxes'):
        if part in parts:
            parts[part].set_color('#333333')
    ax.set_xticks(positions)
    ax.set_xticklabels(labels)
    ax.set_ylabel('Price (pence per litre)')
    ax.set_title('Price Distribution by Fuel Type (outliers excluded)')
    ax.grid(axis='y', alpha=0.3)
    return fig_to_b64(fig)

def plot_boxplot(stats, rows):
    """Box plot showing spread and IQR."""
    fig, ax = plt.subplots(figsize=(10, 5.5))
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    data = []
    labels = []
    by_fuel = defaultdict(list)
    for r in rows:
        by_fuel[r['fuel_type']].append(r['price_pence'])
    for ft in fuel_order:
        if ft in by_fuel and len(by_fuel[ft]) > 0:
            data.append(by_fuel[ft])
            labels.append(ft)
    bp = ax.boxplot(data, labels=labels, patch_artist=True, widths=0.55,
                    medianprops={'color': '#333', 'linewidth': 1.5},
                    flierprops={'marker': '.', 'alpha': 0.4, 'markersize': 3})
    for i, box in enumerate(bp['boxes']):
        box.set_facecolor(PALETTE[i % len(PALETTE)])
        box.set_alpha(0.75)
    ax.set_ylabel('Price (pence per litre)')
    ax.set_title('Price Spread — Box Plot by Fuel Type (outliers excluded)')
    ax.grid(axis='y', alpha=0.3)
    return fig_to_b64(fig)

def plot_spread_bars(stats):
    """Bar chart comparing max-min spread and IQR per fuel type."""
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    fig, ax = plt.subplots(figsize=(10, 5))
    x = np.arange(len(fuel_order))
    spreads = [stats[ft]['spread'] if ft in stats else 0 for ft in fuel_order]
    iqrs = [stats[ft]['iqr'] if ft in stats else 0 for ft in fuel_order]
    w = 0.35
    bars1 = ax.bar(x - w/2, spreads, w, label='Max − Min Spread', color='#E88D72', alpha=0.9)
    bars2 = ax.bar(x + w/2, iqrs, w, label='Interquartile Range (IQR)', color='#6A9FB5', alpha=0.9)
    for bar in bars1:
        h = bar.get_height()
        ax.text(bar.get_x() + bar.get_width()/2., h + 0.3, f'{h:.1f}', ha='center', va='bottom', fontsize=8)
    for bar in bars2:
        h = bar.get_height()
        ax.text(bar.get_x() + bar.get_width()/2., h + 0.3, f'{h:.1f}', ha='center', va='bottom', fontsize=8)
    ax.set_xticks(x)
    ax.set_xticklabels(fuel_order)
    ax.set_ylabel('Pence per Litre')
    ax.set_title('Price Spread vs IQR by Fuel Type — Competitiveness Indicators')
    ax.legend()
    ax.grid(axis='y', alpha=0.3)
    return fig_to_b64(fig)

def plot_update_lag(lag_stats, rows):
    """Histogram / KDE of update lag, and per-fuel bar chart."""
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 5))

    # Left: overall lag histogram
    all_lags = [r['update_lag_hours'] for r in rows]
    ax1.hist(all_lags, bins=80, color=PALETTE[0], edgecolor='white', alpha=0.8)
    ax1.axvline(np.median(all_lags), color='#d62728', linestyle='--', linewidth=1.5,
                label=f"Median: {np.median(all_lags):.1f}h")
    ax1.set_xlabel('Update Lag (hours)')
    ax1.set_ylabel('Number of Records')
    ax1.set_title('Distribution of Retailer Price Update Lag')
    ax1.legend()
    ax1.grid(axis='y', alpha=0.3)

    # Right: per-fuel-type median lag
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    medians = []
    p90s = []
    labels = []
    for ft in fuel_order:
        if ft in lag_stats:
            medians.append(lag_stats[ft]['median'])
            p90s.append(lag_stats[ft]['p90'])
            labels.append(ft)
    x = np.arange(len(labels))
    w = 0.35
    ax2.bar(x - w/2, medians, w, label='Median Lag', color='#6A9FB5', alpha=0.9)
    ax2.bar(x + w/2, p90s, w, label='P90 Lag', color='#E88D72', alpha=0.9)
    ax2.set_xticks(x)
    ax2.set_xticklabels(labels)
    ax2.set_ylabel('Hours')
    ax2.set_title('Update Lag by Fuel Type (Median & P90)')
    ax2.legend()
    ax2.grid(axis='y', alpha=0.3)

    plt.tight_layout()
    return fig_to_b64(fig)

def plot_station_fuel_coverage(cov):
    """Pie chart of stations by number of fuel types offered."""
    fig, ax = plt.subplots(figsize=(7, 5))
    dist = cov['distribution']
    labels = [f'{k} fuel type{"s" if k > 1 else ""}' for k in dist.keys()]
    sizes = list(dist.values())
    colors = PALETTE[:len(sizes)]
    wedges, texts, autotexts = ax.pie(sizes, labels=labels, autopct='%1.1f%%',
                                        colors=colors, startangle=140)
    ax.set_title('Stations by Number of Fuel Types Reported')
    return fig_to_b64(fig)

def plot_fuel_type_coverage_bar(cov):
    """Horizontal bar of station counts per fuel type."""
    fig, ax = plt.subplots(figsize=(8, 4))
    fsc = cov['fuel_station_counts']
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    items = [(ft, fsc.get(ft, 0)) for ft in fuel_order if ft in fsc]
    items.sort(key=lambda x: x[1], reverse=True)
    labels = [x[0] for x in items]
    vals = [x[1] for x in items]
    colors = [PALETTE_DICT.get(l, PALETTE[0]) for l in labels]
    bars = ax.barh(labels, vals, color=colors, alpha=0.85)
    for bar, v in zip(bars, vals):
        ax.text(bar.get_width() + 20, bar.get_y() + bar.get_height()/2,
                str(v), va='center', fontsize=10)
    ax.set_xlabel('Number of Unique Stations')
    ax.set_title('Station Coverage by Fuel Type')
    ax.set_xlim(0, max(vals) * 1.15)
    ax.grid(axis='x', alpha=0.3)
    return fig_to_b64(fig)

# ── HTML Report ───────────────────────────────────────────────────────────────
def fmt_pence(v):
    """Format as £X.XX."""
    return f'£{v/100:.2f}'

def stat_row(label, val, unit=''):
    return f'<tr><td>{label}</td><td>{val}{unit}</td></tr>'

def fuel_stat_table(stats):
    rows_html = ''
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    headers = ['Fuel Type', 'Records', 'Mean (£)', 'Median (£)', 'Min (£)', 'Max (£)',
               'Std Dev (£)', 'IQR (£)', 'Spread (£)']
    rows_html += '<thead><tr>' + ''.join(f'<th>{h}</th>' for h in headers) + '</tr></thead><tbody>'
    for ft in fuel_order:
        if ft not in stats:
            continue
        s = stats[ft]
        rows_html += f'''<tr>
            <td><strong>{ft}</strong></td>
            <td>{s['count']:,}</td>
            <td>{fmt_pence(s['mean'])}</td>
            <td>{fmt_pence(s['median'])}</td>
            <td>{fmt_pence(s['min'])}</td>
            <td>{fmt_pence(s['max'])}</td>
            <td>{fmt_pence(s['std'])}</td>
            <td>{fmt_pence(s['iqr'])}</td>
            <td>{fmt_pence(s['spread'])}</td>
        </tr>'''
    rows_html += '</tbody>'
    return f'<table class="stat-table">{rows_html}</table>'

def lag_stat_table(lag_stats):
    rows_html = ''
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    headers = ['Fuel Type', 'Mean (h)', 'Median (h)', 'P90 (h)', 'P95 (h)', 'Max (h)']
    rows_html += '<thead><tr>' + ''.join(f'<th>{h}</th>' for h in headers) + '</tr></thead><tbody>'
    for ft in fuel_order:
        if ft not in lag_stats:
            continue
        s = lag_stats[ft]
        rows_html += f'''<tr>
            <td><strong>{ft}</strong></td>
            <td>{s['mean']:.1f}</td>
            <td>{s['median']:.1f}</td>
            <td>{s['p90']:.1f}</td>
            <td>{s['p95']:.1f}</td>
            <td>{s['max']:.1f}</td>
        </tr>'''
    rows_html += '</tbody>'
    return f'<table class="stat-table">{rows_html}</table>'

def build_html(stats, lag_stats, cov, rows, clean_rows, flagged, outlier_bounds, date_range):
    # Images
    violin_b64 = plot_price_distribution(stats, clean_rows)
    box_b64 = plot_boxplot(stats, clean_rows)
    spread_b64 = plot_spread_bars(stats)
    lag_b64 = plot_update_lag(lag_stats, rows)
    station_pie_b64 = plot_station_fuel_coverage(cov)
    coverage_bar_b64 = plot_fuel_type_coverage_bar(cov)

    # Overview KPIs
    total_records = len(rows)
    total_clean = len(clean_rows)
    total_flagged = len(flagged)
    total_stations = cov['total_stations']
    fuel_types_found = sorted(set(r['fuel_type'] for r in rows))

    # Data quality note
    outlier_pct = (total_flagged / total_records * 100) if total_records else 0

    # Station coverage text
    dist_items = sorted(cov['distribution'].items())
    dist_text = ', '.join(f'{cnt} stations report {k} fuel type{"s" if k > 1 else ""}'
                          for k, cnt in dist_items)

    # Key findings — based on data
    e10_stats = stats.get('E10', {})
    b7_stats = stats.get('B7_STANDARD', {})
    e5_stats = stats.get('E5', {})
    b7p_stats = stats.get('B7_PREMIUM', {})

    most_expensive = max(stats.keys(), key=lambda ft: stats[ft]['mean'])
    least_expensive = min(stats.keys(), key=lambda ft: stats[ft]['mean'])
    highest_spread = max(stats.keys(), key=lambda ft: stats[ft]['spread'])
    highest_iqr = max(stats.keys(), key=lambda ft: stats[ft]['iqr'])

    # Median lags across all fuel types
    overall_lags = np.array([r['update_lag_hours'] for r in rows])
    overall_median_lag = np.median(overall_lags)

    html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>UK Retail Fuel Price Trend Analysis — February 2026</title>
<style>
* {{ margin:0; padding:0; box-sizing:border-box; }}
body {{
    font-family: 'Segoe UI', 'DejaVu Sans', Arial, sans-serif;
    background: #f5f6f8;
    color: #1a1a2e;
    line-height: 1.6;
}}
.container {{ max-width: 1100px; margin: 0 auto; padding: 2rem 1.5rem; }}
header {{
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    color: white;
    padding: 3rem 1.5rem 2.5rem;
    text-align: center;
}}
header h1 {{ font-size: 2rem; font-weight: 700; margin-bottom: 0.5rem; }}
header p {{ font-size: 1.05rem; opacity: 0.85; max-width: 700px; margin: 0 auto; }}
header .meta {{ margin-top: 1.2rem; font-size: 0.85rem; opacity: 0.7; }}

.section {{
    background: white;
