def main():
    print("Loading data...")
    rows = load_data()
    print(f"  Loaded {len(rows)} records")

    print("Filtering outliers...")
    clean_rows, flagged, bounds = filter_outliers_iqr(rows)
    print(f"  Clean: {len(clean_rows)}, Flagged: {len(flagged)}")

    print("Computing statistics...")
    stats = fuel_stats(clean_rows)
    lag_stats = update_lag_stats(rows)
    cov = station_coverage(rows, clean_rows)

    date_range = {
        'recorded_from': min(r['recorded_at_dt'] for r in rows),
        'recorded_to': max(r['recorded_at_dt'] for r in rows),
        'source_from': min(r['source_updated_at_dt'] for r in rows),
        'source_to': max(r['source_updated_at_dt'] for r in rows),
    }

    print("Generating report...")
    html = build_html(stats, lag_stats, cov, rows, clean_rows, flagged, bounds, date_range)

    out_path = '/app/output/final_report.html'
    with open(out_path, 'w') as f:
        f.write(html)
    print(f"Report written to {out_path} ({len(html):,} bytes)")

    # Write task_input KPIs summary for verification
    kpi_data = {
        "average_price_per_litre_by_fuel_type": {
            ft: round(s['mean'], 2) for ft, s in stats.items()
        },
        "price_spread_max_min_by_fuel_type": {
            ft: round(s['spread'], 2) for ft, s in stats.items()
        },
        "iqr_by_fuel_type": {
            ft: round(s['iqr'], 2) for ft, s in stats.items()
        },
        "median_update_lag_hours": float(np.median([r['update_lag_hours'] for r in rows])),
        "unique_station_count": cov['total_stations'],
        "data_quality": {
            "total_records": len(rows),
            "clean_records": len(clean_rows),
            "flagged_outliers": len(flagged),
            "outlier_pct": round(len(flagged) / len(rows) * 100, 2),
            "fuel_types": sorted(set(r['fuel_type'] for r in rows)),
            "date_range": {
                "recorded_from": str(date_range['recorded_from']),
                "recorded_to": str(date_range['recorded_to']),
            }
        }
    }
    with open('/app/output/kpi_summary.json', 'w') as f:
        json.dump(kpi_data, f, indent=2, default=str)
    print("KPI summary written to /app/output/kpi_summary.json")

if __name__ == '__main__':
    main()

